package com.example.statusdrafter.service; import com.example.statusdrafter.entity.*; import com.example.statusdrafter.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.stream.*;
@Service public class ReportService {private final TaskRepository tasks; private final UserRepository users; public ReportService(TaskRepository t,UserRepository u){tasks=t;users=u;} public Map<String,Long> employee(User u){Map<String,Long> m=new LinkedHashMap<>();m.put("Total",tasks.countByEmployee(u));for(Task.Status s:Task.Status.values())m.put(label(s),tasks.countByEmployeeAndStatus(u,s));m.put("Overdue",(long)tasks.findByDeadlineBeforeAndStatusNotAndEmployeeOrderByDeadlineAsc(LocalDate.now(),Task.Status.COMPLETED,u).size());return m;} public Map<String,Long> overall(){Map<String,Long> m=new LinkedHashMap<>();m.put("Employees",users.countByRole(User.Role.EMPLOYEE));m.put("Total Tasks",tasks.count());for(Task.Status s:Task.Status.values())m.put(label(s),tasks.countByStatus(s));m.put("Overdue",(long)tasks.findByDeadlineBeforeAndStatusNotOrderByDeadlineAsc(LocalDate.now(),Task.Status.COMPLETED).size());return m;} private String label(Task.Status s){return switch(s){case NOT_STARTED->"Not Started";case IN_PROGRESS->"In Progress";case COMPLETED->"Completed";case ON_HOLD->"On Hold";case BLOCKED->"Blocked";};} public Map<String,Object> period(User u,String period){LocalDate today=LocalDate.now();LocalDate start=switch(period==null?"monthly":period.toLowerCase()){case "daily"->today;case "weekly"->today.minusDays(6);default->today.withDayOfMonth(1);};Map<String,Object> out=new LinkedHashMap<>();out.put("period",period==null?"monthly":period);out.put("tasksUpdated",tasks.countByEmployeeAndUpdatedAtBetween(u,start.atStartOfDay(),today.plusDays(1).atStartOfDay()));return out;} public long percent(Map<String,Long> m){long total=m.getOrDefault("Total",m.getOrDefault("Total Tasks",0L));return total==0?0:Math.round(m.getOrDefault("Completed",0L)*100.0/total);} }
